#!/bin/sh
# Nightly log backup. Bundles logs/ into a dated tarball and copies it to the destination.
set -eu

DEST="${BACKUP_DEST:-}"  # set via BACKUP_DEST env (host:path, host:/path, or local dir)
STAMP=$(date +%Y%m%d-%H%M%S)
BUNDLE="logs-$STAMP.tar.gz"

[ -n "$DEST" ] || { echo "backup: no destination set (set BACKUP_DEST)" >&2; exit 1; }

tar -czf "$BUNDLE" logs/

# Split DEST into host and path; a bare path (no host) is a local copy.
case "$DEST" in
  *":*"*) HOST=${DEST%%:*}; REMOTE_PATH=${DEST#*:}
          ;;
  *)      HOST=""; REMOTE_PATH=$DEST
          ;;
esac

if [ -n "$HOST" ]; then
  case "$REMOTE_PATH" in
    /*) RSPEC="$HOST:$REMOTE_PATH" ;;
    *)  RSPEC="$HOST:./$REMOTE_PATH" ;;
  esac
  scp -q "$BUNDLE" "$RSPEC"
else
  cp "$BUNDLE" "$REMOTE_PATH/"
fi

echo "backed up logs/ to $DEST ($(wc -c < "$BUNDLE" | tr -d ' ') bytes)"
